{"code": "module RAM #(parameter WIDTH = 6, DEPTH = 8) (
    input wire clk,
    input wire rst_n,
    input wire write_en,
    input wire [$clog2(DEPTH)-1:0] write_addr,
    input wire [WIDTH-1:0] write_data,
    input wire read_en,
    input wire [$clog2(DEPTH)-1:0] read_addr,
    output reg [WIDTH-1:0] read_data
);

    // Internal RAM array
    reg [WIDTH-1:0] internal_RAM [0:DEPTH-1];

    // Write operation
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // Reset all memory locations to 0
            integer i;
            for (i = 0; i < DEPTH; i = i + 1) begin
                internal_RAM[i] <= {WIDTH{1'b0}};
            end
        end else if (write_en) begin
            // Write data to the specified address
            internal_RAM[write_addr] <= write_data;
        end
    end

    // Read operation
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // Reset read_data to 0
            read_data <= {WIDTH{1'b0}};
        end else if (read_en) begin
            // Read data from the specified address
            read_data <= internal_RAM[read_addr];
        end else begin
            // Clear read_data if read_en is not active
            read_data <= {WIDTH{1'b0}};
        end
    end

endmodule
", "description": "This module implements a dual-port RAM with specified depth and width, allowing simultaneous read and write operations. It initializes all data to zero and handles both read and write operations based on enable signals."}

